(*===================================================================================
        Default Variable Assignments
=====================================================================================*)
{region 'State Update'}
    eCurrentState   := eNextState;   
{endregion}

{region 'Default Outputs'}
    LVBreaker.DQ.xCmdOpen          := FALSE;
    LVBreaker.DQ.xCmdClose         := FALSE;
{endregion}

{region 'Default Requests'}
    xOpenRequestPulse   := FALSE;
    xCloseRequestPulse  := FALSE;
{endregion}

(*===================================================================================
                                    Timers Control
=====================================================================================*)
{region 'Request Edge Detection'}
(*-----------------------------------------------------------------------------------
    Each raw request is monitored continuously, irrespective of the selected mode.
-------------------------------------------------------------------------------------*)
    rtAutoOpenRequest(
        CLK := xAutoOpenRequest
    );
    rtAutoCloseRequest(
        CLK := xAutoCloseRequest
    );
    rtHMIOpenRequest(
        CLK := LVBreaker.HMI.xHMIOpenRequest
    );
    rtHMICloseRequest(
        CLK := LVBreaker.HMI.xHMICloseRequest
    );
    rtHMIResetRequest(
        CLK := LVBreaker.HMI.xHMIResetRequest
    );
    rtHMIAlarmAcknowledge(
        CLK := LVBreaker.HMI.xHMIAlarmAcknowledge
    );
{endregion}

{region 'Feedback Debounce'}
(*-------------------------------------------------------------------------------------
        Start timing whenever the physical input differs from
        the currently accepted debounced value.
---------------------------------------------------------------------------------------*)
    tonOpenFeedbackDebounce(
        IN := LVBreaker.DI.xOpenFeedback <> xOpenFeedbackDebounced,
        PT := tFeedbackDebounce
    );
    IF tonOpenFeedbackDebounce.Q THEN
        xOpenFeedbackDebounced := LVBreaker.DI.xOpenFeedback;
    END_IF;

    tonCloseFeedbackDebounce(
        IN := LVBreaker.DI.xCloseFeedback <> xCloseFeedbackDebounced,
        PT := tFeedbackDebounce
    );
    IF tonCloseFeedbackDebounce.Q THEN
        xCloseFeedbackDebounced := LVBreaker.DI.xCloseFeedback;
    END_IF;
{endregion}

{region 'Feedback Fault Delay'}
(*-------------------------------------------------------------------------------------
    Outside a PLC-controlled transition, exactly one breaker-position feedback
    must be active. Allow temporary invalid feedback during contact changeover
    or external breaker movement.
---------------------------------------------------------------------------------------*)
    tonFeedbackFaultDelay(
        IN :=   (xOpenFeedbackDebounced = xCloseFeedbackDebounced)
                AND (eRackPosition = LVBreakerRackPosition#RACKED_IN
                     OR eRackPosition = LVBreakerRackPosition#TEST)
                AND (eCurrentState <> LVBreakerState#OPENING)
                AND (eCurrentState <> LVBreakerState#CLOSING)
                AND (eCurrentState <> LVBreakerState#RETRY_WAIT),
    
        PT := tFeedbackFaultDelay
    );
{endregion}

{region 'Rack Position Debounce'}
(*-------------------------------------------------------------------------------------
        Debounce Racked-In, Racked-Out and Test Signals
---------------------------------------------------------------------------------------*)
    tonRackedInDebounce(
        IN := LVBreaker.DI.xRackedIN <> xRackedInDebounced,
        PT := tFeedbackDebounce
    );
    IF tonRackedInDebounce.Q THEN
        xRackedInDebounced := LVBreaker.DI.xRackedIN;
    END_IF;
    
    tonRackedOutDebounce(
        IN := LVBreaker.DI.xRackedOUT <> xRackedOutDebounced,
        PT := tFeedbackDebounce
    );
    IF tonRackedOutDebounce.Q THEN
        xRackedOutDebounced := LVBreaker.DI.xRackedOUT;
    END_IF;
    
    tonTestPositionDebounce(
        IN := LVBreaker.DI.xTestPosition <> xTestPositionDebounced,
        PT := tFeedbackDebounce
    ); 
    IF tonTestPositionDebounce.Q THEN
        xTestPositionDebounced := LVBreaker.DI.xTestPosition;
    END_IF;
{endregion}

{region 'Ready To Close Validation'}
(*-------------------------------------------------------------------------------------
        The field signal must remain true for the debounce period.
        A false input removes readiness immediately.
---------------------------------------------------------------------------------------*)
    tonFieldReadyToClose(
        IN := LVBreaker.DI.xFieldReadyToClose,
        PT := tFeedbackDebounce
    );
    
    xFieldReadyToCloseValid := tonFieldReadyToClose.Q;
{endregion}

{region 'Command Timers'}
(*-------------------------------------------------------------------------------------
    A pulse timer runs only while in FSM Transition States.
    Timeout timers for complete operation.
---------------------------------------------------------------------------------------*)
    tonOpenPulse(
        IN := eCurrentState = LVBreakerState#OPENING,
        PT := tOpenPulse
    );
    tonOpenTimeout(
        IN := eCurrentState = LVBreakerState#OPENING,
        PT := tOpenTimeout
    );
    tonClosePulse(
        IN := eCurrentState = LVBreakerState#CLOSING,
        PT := tClosePulse
    );
    tonCloseTimeout(
        IN := eCurrentState = LVBreakerState#CLOSING,
        PT := tCloseTimeout
    );
{endregion}

(*===================================================================================
                                    Process Inputs
=====================================================================================*)
{region 'Operating Mode'}
(*-----------------------------------------------------------------------------------
                            OPERATING MODE SELECTION
                0:  INVALID
                1:  AUTO
                2:  MANUAL
                3:  TEST
                4:  MAINTENANCE
                5:  DISABLED
-------------------------------------------------------------------------------------*)
    IF NOT xEnable THEN
        eOperatingMode := LVBreakerMode#DISABLED;
    ELSIF LVBreaker.DI.xMaintenance THEN
        eOperatingMode := LVBreakerMode#MAINTENANCE;
    ELSE
        CASE uiModeRequest OF
    
            1:
                eOperatingMode := LVBreakerMode#AUTO;
            2:
                eOperatingMode := LVBreakerMode#MANUAL;
            3:
                eOperatingMode := LVBreakerMode#TEST;
            4:
                eOperatingMode := LVBreakerMode#MAINTENANCE;
            5:
                eOperatingMode := LVBreakerMode#DISABLED;
            ELSE
                eOperatingMode := LVBreakerMode#INVALID;
        END_CASE;
    END_IF;
{endregion}

{region 'Rack Position Decode'}
(*-------------------------------------------------------------------------------------
                                Determine Rack Position
---------------------------------------------------------------------------------------*)
    IF xRackedInDebounced AND NOT xTestPositionDebounced AND NOT xRackedOutDebounced THEN
        
        eRackPosition := LVBreakerRackPosition#RACKED_IN;
        
    ELSIF xTestPositionDebounced AND NOT xRackedInDebounced AND NOT xRackedOutDebounced THEN
    
        eRackPosition := LVBreakerRackPosition#TEST;
    
    ELSIF xRackedOutDebounced AND NOT xRackedInDebounced AND NOT xTestPositionDebounced THEN
    
        eRackPosition := LVBreakerRackPosition#RACKED_OUT;
    
    ELSIF NOT xRackedInDebounced AND NOT xTestPositionDebounced AND NOT xRackedOutDebounced THEN
        // Breaker may be travelling between rack positions
        eRackPosition := LVBreakerRackPosition#UNKNOWN;
    ELSE
        // Two or more position contacts are active
        eRackPosition := LVBreakerRackPosition#INVALID;
    
    END_IF;
{endregion}

{region 'Control Authority'}
(*-----------------------------------------------------------------------------------
                        PLC CONTROL AUTHORITY
            Mode selects the request source.
            Authority determines whether the PLC may operate the coils.
-------------------------------------------------------------------------------------*)
    CASE eOperatingMode OF
    
        LVBreakerMode#AUTO,
        LVBreakerMode#MANUAL:
    
            xControlAllowed     :=  xPLCControlAuthority
                                    AND eRackPosition = LVBreakerRackPosition#RACKED_IN;
    
        LVBreakerMode#TEST:
    
            xControlAllowed     :=  xPLCControlAuthority
                                    AND eRackPosition = LVBreakerRackPosition#TEST;
    
        ELSE
    
            xControlAllowed := FALSE;
    
    END_CASE;
{endregion}

{region 'Request Source Selection'}
(*-------------------------------------------------------------------------------------
                            Determine Type of Request
---------------------------------------------------------------------------------------*)
    CASE eOperatingMode OF
    
        LVBreakerMode#AUTO:
            xOpenRequestPulse  := rtAutoOpenRequest.Q;
            xCloseRequestPulse := rtAutoCloseRequest.Q;
    
        LVBreakerMode#MANUAL,
        LVBreakerMode#TEST:
            xOpenRequestPulse  := rtHMIOpenRequest.Q;
            xCloseRequestPulse := rtHMICloseRequest.Q;
    
    END_CASE;
{endregion}

{region 'Calculate Faults'}
(*-----------------------------------------------------------------------------------
                            Calculate Faults
-------------------------------------------------------------------------------------*)
    //Feedback Fault IF:     Open AND closed
    LVBreaker.Faults.xFeedbackFault             :=  tonFeedbackFaultDelay.Q;
    
    //Rack Position Fault IF:     RackPosition = Invalid
    LVBreaker.Faults.xRackPositionFault         :=  eRackPosition = LVBreakerRackPosition#INVALID;
    
    //Control Supply Fault IF:     Report any control-supply problem
    LVBreaker.Faults.xControlSupplyFault        :=  LVBreaker.DI.xMainControlSupplyTripped
                                                    OR  LVBreaker.DI.xMotorSupplyTripped
                                                    OR  LVBreaker.DI.xOpenCoilSupplyTripped
                                                    OR  LVBreaker.DI.xCloseCoilSupplyTripped;
    
    // Major fault: unreliable feedback or breaker unable to opperate. - Only faults that prevent safe opening are blocking major faults
    LVBreaker.Faults.xFault                     :=  LVBreaker.Faults.xFeedbackFault
                                                    OR LVBreaker.Faults.xRackPositionFault
                                                    OR LVBreaker.DI.xMainControlSupplyTripped
                                                    OR LVBreaker.DI.xOpenCoilSupplyTripped;
    
{endregion}

{region 'Derive Statuses'}
(*-----------------------------------------------------------------------------------
                                Set Statusses
-------------------------------------------------------------------------------------*)
        LVBreaker.Status.xOpen                  :=  xOpenFeedbackDebounced
                                                    AND NOT xCloseFeedbackDebounced;
        
        LVBreaker.Status.xClosed                :=  xCloseFeedbackDebounced
                                                    AND NOT xOpenFeedbackDebounced;
        
        LVBreaker.Status.xTripped               :=  LVBreaker.DI.xTrippedFeedback;
        
        LVBreaker.Status.xPLCControlAuthority   :=  xPLCControlAuthority;
        
        LVBreaker.Status.xReadyToClose          :=  xFieldReadyToCloseValid
                                                    AND LVBreaker.Status.xOpen
                                                    AND NOT LVBreaker.DI.xTrippedFeedback
                                                    AND NOT LVBreaker.Faults.xControlSupplyFault
                                                    AND (eRackPosition = LVBreakerRackPosition#RACKED_IN OR eRackPosition = LVBreakerRackPosition#TEST);
        // A PLC command is active
        LVBreaker.Status.xCommandBusy           := (eCurrentState = LVBreakerState#OPENING)
                                                    OR (eCurrentState = LVBreakerState#CLOSING)
                                                    OR (eCurrentState = LVBreakerState#RETRY_WAIT);

        LVBreaker.Status.xRetryPending          :=  eCurrentState = LVBreakerState#RETRY_WAIT;
        
        // PLC is currently capable of opening the breaker
        LVBreaker.Status.xCanOpen               :=  xControlAllowed
                                                    AND LVBreaker.Status.xClosed
                                                    AND LVBreaker.Interlocks.xExternalOpenPermit
                                                    AND NOT LVBreaker.DI.xTrippedFeedback
                                                    AND NOT LVBreaker.Faults.xFault;

        // PLC is currently capable of closing the breaker
        LVBreaker.Status.xCanClose              :=  xControlAllowed
                                                    AND LVBreaker.Status.xReadyToClose
                                                    AND LVBreaker.Interlocks.xExternalClosePermit
                                                    AND NOT LVBreaker.Faults.xFault;
        
        // The FB is in Auto and the PLC has breaker-control authority
        LVBreaker.Status.xAutoControlActive      := (eOperatingMode = LVBreakerMode#AUTO)
                                                    AND xControlAllowed;
    
        
    
{endregion}

{region 'Acknowledge  Alarms'}
    IF rtHMIAlarmAcknowledge.Q THEN
        LVBreaker.Alarms.xFailToOpen  := FALSE;
        LVBreaker.Alarms.xFailToClose := FALSE;
    END_IF;
{endregion}

(*===================================================================================
                                LV BREAKER FSM
=====================================================================================*)

{region 'FSM'}
(*-----------------------------------------------------------------------------------
                                FSM opperation
-------------------------------------------------------------------------------------*)
    IF NOT xEnable THEN
        eNextState := LVBreakerState#UNKNOWN;
        LVBreaker.Status.uiRetriesUsed := 0;
    ELSIF LVBreaker.DI.xTrippedFeedback THEN
        eNextState := LVBreakerState#TRIPPED;
    ELSIF LVBreaker.Faults.xFault THEN
        eNextState := LVBreakerState#FAULT;
    ELSE
    
        CASE eCurrentState OF
    
            LVBreakerState#UNKNOWN:
            
                    IF xOpenFeedbackDebounced AND NOT xCloseFeedbackDebounced THEN
                        
                        eNextState := LVBreakerState#OPEN;
                        
                    ELSIF xCloseFeedbackDebounced AND NOT xOpenFeedbackDebounced THEN
                        
                        eNextState := LVBreakerState#CLOSED;
                        
                    END_IF;
    
            LVBreakerState#OPEN:
            
                    IF xControlAllowed THEN
                        
                        IF xCloseRequestPulse AND LVBreaker.Status.xCanClose THEN
                            LVBreaker.Status.uiRetriesUsed  := 0;
                            eRetryTargetState               := LVBreakerState#CLOSING;
                            eNextState                      := LVBreakerState#CLOSING;
                        ELSIF NOT LVBreaker.Status.xOpen THEN
                            eNextState                      := LVBreakerState#UNKNOWN;
                        END_IF;  
                        
                    ELSIF NOT LVBreaker.Status.xOpen THEN
                        //Breaker isnt Open Anymore
                        eNextState := LVBreakerState#UNKNOWN;
                    END_IF;

            LVBreakerState#CLOSED:
    
                    IF xControlAllowed THEN
                        
                        IF xOpenRequestPulse AND LVBreaker.Status.xCanOpen THEN
                            LVBreaker.Status.uiRetriesUsed := 0;
                            eRetryTargetState              := LVBreakerState#OPENING;
                            eNextState                     := LVBreakerState#OPENING;
                        ELSIF NOT LVBreaker.Status.xClosed THEN
                            eNextState                      := LVBreakerState#UNKNOWN;
                        END_IF;  
                        
                    ELSIF NOT LVBreaker.Status.xClosed THEN
                        //Breaker isnt Closed Anymore
                        eNextState := LVBreakerState#UNKNOWN;
                    END_IF;
    
            LVBreakerState#TRIPPED:
            
                    IF xOpenFeedbackDebounced AND NOT xCloseFeedbackDebounced THEN
    
                        eNextState := LVBreakerState#OPEN;
                
                    ELSIF xCloseFeedbackDebounced AND NOT xOpenFeedbackDebounced THEN
    
                        eNextState := LVBreakerState#CLOSED;
                
                    ELSE
                        // Trip cleared, but no stable position is confirmed
                        eNextState := LVBreakerState#UNKNOWN;
                
                    END_IF;
    
            LVBreakerState#OPENING:
            
                    IF xControlAllowed THEN
                        
                        IF LVBreaker.Status.xOpen THEN
                            // Opening completed
                            eNextState := LVBreakerState#OPEN;
                        ELSIF NOT LVBreaker.Interlocks.xExternalOpenPermit THEN
                            // Opening is no longer allowed
                            eNextState := LVBreakerState#UNKNOWN;
                        ELSE
                            //Check timeout
                            IF tonOpenTimeout.Q THEN
                                
                                    //check retries only from a known, safe starting position
                                    IF LVBreaker.Status.uiRetriesUsed < uiMaxRetries AND LVBreaker.Status.xCanOpen THEN
                                            LVBreaker.Status.uiRetriesUsed  := LVBreaker.Status.uiRetriesUsed + 1;
                                            eNextState                      := LVBreakerState#RETRY_WAIT;
                                    ELSE
                                            LVBreaker.Alarms.xFailToOpen    := TRUE;
                                            eNextState                      := LVBreakerState#UNKNOWN;
                                    END_IF;
                                    
                            ELSE
                                LVBreaker.DQ.xCmdOpen := NOT tonOpenPulse.Q;
                            END_IF;
                           
                        END_IF;
                        
                    ELSE
                        //PLC Has NO CONTROL
                        eNextState := LVBreakerState#UNKNOWN;
                    END_IF;
    
            LVBreakerState#CLOSING:
            
                    IF xControlAllowed THEN
                        
                        IF LVBreaker.Status.xClosed THEN
                            // Closing completed
                            eNextState := LVBreakerState#Closed;
                        ELSIF NOT LVBreaker.Interlocks.xExternalClosePermit THEN
                            // Closing is no longer allowed
                            eNextState := LVBreakerState#UNKNOWN;
                        ELSIF LVBreaker.Faults.xControlSupplyFault THEN
                            //Fault occured with Control Supply
                            eNextState := LVBreakerState#UNKNOWN;
                        ELSE
                            //Check timeout
                            IF tonCloseTimeout.Q THEN
                                
                                    //check retries only from a known, safe starting position
                                    IF LVBreaker.Status.uiRetriesUsed < uiMaxRetries AND LVBreaker.Status.xCanClose THEN
                                            LVBreaker.Status.uiRetriesUsed  := LVBreaker.Status.uiRetriesUsed + 1;
                                            eNextState                      := LVBreakerState#RETRY_WAIT;
                                    ELSE
                                            LVBreaker.Alarms.xFailToClose   := TRUE;
                                            eNextState                      := LVBreakerState#UNKNOWN;
                                    END_IF;
                                    
                            ELSE
                                LVBreaker.DQ.xCmdClose := NOT tonClosePulse.Q;
                            END_IF;
                           
                        END_IF;
                        
                    ELSE
                        //PLC Has NO CONTROL
                        eNextState := LVBreakerState#UNKNOWN;
                    END_IF;       
    
            LVBreakerState#RETRY_WAIT:

                    IF xControlAllowed THEN
                
                        IF eRetryTargetState = LVBreakerState#OPENING OR eRetryTargetState = LVBreakerState#CLOSING THEN
                            eNextState := eRetryTargetState;
                        ELSE
                            eNextState := LVBreakerState#INVALID;
                        END_IF;
                
                    ELSE
                        eNextState := LVBreakerState#UNKNOWN;
                    END_IF;
    
            LVBreakerState#FAULT:

                    IF xControlAllowed THEN
                        
                        IF rtHMIResetRequest.Q AND NOT LVBreaker.Faults.xFault THEN           
                                eNextState := LVBreakerState#UNKNOWN;        
                        END_IF;
                        
                    ELSE
                        // Observer mode automatically recovers when the fault clears
                        IF NOT LVBreaker.Faults.xFault THEN
                            eNextState := LVBreakerState#UNKNOWN;
                        END_IF;
                        
                    END_IF;
    
            LVBreakerState#INVALID:
                    IF xOpenFeedbackDebounced AND NOT xCloseFeedbackDebounced THEN
                
                        eNextState := LVBreakerState#OPEN;
                
                    ELSIF xCloseFeedbackDebounced AND NOT xOpenFeedbackDebounced THEN
                
                        eNextState := LVBreakerState#CLOSED;
                
                    ELSIF NOT xOpenFeedbackDebounced AND NOT xCloseFeedbackDebounced THEN
                
                        eNextState := LVBreakerState#UNKNOWN;
                
                    END_IF;
    
    
            ELSE
                eNextState := LVBreakerState#INVALID;
        END_CASE;
    END_IF;
{endregion}

(*===================================================================================
                                    Set Outputs
=====================================================================================*)

{region 'Publish Operating Mode'}
(*-----------------------------------------------------------------------------------
                                Mode Control
-------------------------------------------------------------------------------------*)
    LVBreaker.OperatingMode := eOperatingMode;
    
    CASE eOperatingMode OF
    
        LVBreakerMode#INVALID:
            LVBreaker.uiOperatingMode := 0;
        LVBreakerMode#AUTO:
            LVBreaker.uiOperatingMode := 1;
        LVBreakerMode#MANUAL:
            LVBreaker.uiOperatingMode := 2;
        LVBreakerMode#TEST:
            LVBreaker.uiOperatingMode := 3;
        LVBreakerMode#MAINTENANCE:
            LVBreaker.uiOperatingMode := 4;
        LVBreakerMode#DISABLED:
            LVBreaker.uiOperatingMode := 5;
        ELSE
            LVBreaker.uiOperatingMode := 0;
    END_CASE;
{endregion}

{region 'Publish Current State'}
(*-----------------------------------------------------------------------------------
                                State Control
-------------------------------------------------------------------------------------*)
    LVBreaker.State := eCurrentState;

    CASE eCurrentState OF
    
        LVBreakerState#UNKNOWN:
            LVBreaker.uiState := 0;
        LVBreakerState#OPEN:
            LVBreaker.uiState := 1;
        LVBreakerState#CLOSED:
            LVBreaker.uiState := 2;
        LVBreakerState#TRIPPED:
            LVBreaker.uiState := 3;
        LVBreakerState#OPENING:
            LVBreaker.uiState := 4;
        LVBreakerState#CLOSING:
            LVBreaker.uiState := 5;
        LVBreakerState#RETRY_WAIT:
            LVBreaker.uiState := 6;
        LVBreakerState#FAULT:
            LVBreaker.uiState := 7;
        LVBreakerState#INVALID:
            LVBreaker.uiState := 8;
        ELSE
            LVBreaker.uiState := 8;
    END_CASE;
{endregion}

{region 'Publish Rack Position'}
(*-----------------------------------------------------------------------------------
                                Rack Position
-------------------------------------------------------------------------------------*)
    LVBreaker.RackPosition := eRackPosition;
    
    CASE eRackPosition OF

        LVBreakerRackPosition#UNKNOWN:
            LVBreaker.uiRackPosition := 0;
        LVBreakerRackPosition#RACKED_IN:
            LVBreaker.uiRackPosition := 1;
        LVBreakerRackPosition#TEST:
            LVBreaker.uiRackPosition := 2;
        LVBreakerRackPosition#RACKED_OUT:
            LVBreaker.uiRackPosition := 3;
        LVBreakerRackPosition#INVALID:
            LVBreaker.uiRackPosition := 4;
        ELSE
            LVBreaker.uiRackPosition := 4;
    END_CASE;
{endregion}

{region 'Publish Alarms'}
    //General Alarm
    LVBreaker.Alarms.xAlarm     :=  LVBreaker.Alarms.xFailToOpen 
                                    OR LVBreaker.Alarms.xFailToClose;
{endregion}


{region 'Publish Control Owner'}
(*----------------------------------------------------------------------------
                                0 = UNKNOWN
                                1 = PLC
                                2 = DSE
                                3 = LOCAL
------------------------------------------------------------------------------*)
    CASE eOperatingMode OF

        LVBreakerMode#MAINTENANCE:
            LVBreaker.uiControlOwner := 3; // Local

        LVBreakerMode#AUTO,
        LVBreakerMode#MANUAL,
        LVBreakerMode#TEST:

            IF xPLCControlAuthority THEN
                LVBreaker.uiControlOwner := 1; // PLC
            ELSE
                // DHMBG-specific assumption:
                // LV-Q2 to LV-Q4 are DSE-controlled.
                LVBreaker.uiControlOwner := 2; // DSE
            END_IF;

    ELSE
            // Disabled, invalid or unsupported mode
            LVBreaker.uiControlOwner := 0; // Unknown/no active owner
    END_CASE;
{endregion}
